package com.preppulse.controller;
import com.preppulse.model.StudyTask; import com.preppulse.model.StudyTopic; import com.preppulse.service.*;
import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.time.LocalDate; import java.time.LocalTime;
@Controller public class DashboardController {
 private final StudyTaskService tasks; private final SmartPriorityService priority; private final RevisionService revisions; private final StudySettingsService settings; private final InsightsService insights; private final FocusSessionService focus; private final ReminderService reminders;
 public DashboardController(StudyTaskService t,SmartPriorityService p,RevisionService r,StudySettingsService s,InsightsService i,FocusSessionService f,ReminderService m){tasks=t;priority=p;revisions=r;settings=s;insights=i;focus=f;reminders=m;}
 @GetMapping("/") public String dashboard(Model model){fill(model);return "index";}
 private void fill(Model model){var stats=tasks.getStats();var pending=tasks.getPendingTasks();model.addAttribute("stats",stats);model.addAttribute("tasks",tasks.getAllTasks());model.addAttribute("upcoming",tasks.getUpcomingTasks());model.addAttribute("newTask",newTask());model.addAttribute("newTopic",new StudyTopic());model.addAttribute("settings",settings.getOrCreate());model.addAttribute("topics",revisions.list());model.addAttribute("dueReviews",revisions.due());model.addAttribute("recommended",priority.rank(pending,java.time.LocalDateTime.now()).stream().limit(4).toList());model.addAttribute("insights",insights.get());model.addAttribute("recentSessions",focus.recent());model.addAttribute("recentReminders",reminders.recent().stream().limit(5).toList());model.addAttribute("latestReminderId",reminders.latestId());}
 private StudyTask newTask(){StudyTask t=new StudyTask();t.setDueDate(LocalDate.now());t.setDueTime(LocalTime.of(10,0));t.setEstimatedMinutes(30);t.setReminderIntervals("1440,60,15");return t;}
 @PostMapping("/tasks") public String create(@Valid @ModelAttribute("newTask") StudyTask task,BindingResult result,Model model,RedirectAttributes redirect){if(result.hasErrors()){fill(model);model.addAttribute("newTask",task);return "index";}tasks.create(task);redirect.addFlashAttribute("successMessage","Study task added. PrepPulse will help you keep it on track.");return "redirect:/#tasks";}
 @PostMapping("/tasks/{id}/edit") public String edit(@PathVariable Long id,@Valid @ModelAttribute("editedTask") StudyTask edited,BindingResult result,RedirectAttributes redirect){if(result.hasErrors()){redirect.addFlashAttribute("errorMessage","Please check the task details. The title, subject, deadline, and study time are required.");return "redirect:/#tasks";}tasks.update(id,edited);redirect.addFlashAttribute("successMessage","Task details updated.");return "redirect:/#tasks";}
 @PostMapping("/tasks/{id}/toggle") public String toggle(@PathVariable Long id,RedirectAttributes redirect){tasks.toggleCompleted(id);redirect.addFlashAttribute("successMessage","Task progress updated.");return "redirect:/#tasks";}
 @PostMapping("/tasks/{id}/delete") public String delete(@PathVariable Long id,RedirectAttributes redirect){tasks.delete(id);redirect.addFlashAttribute("successMessage","Task deleted.");return "redirect:/#tasks";}
 @PostMapping("/tasks/{id}/postpone") public String postpone(@PathVariable Long id,@RequestParam(defaultValue="1") int days,RedirectAttributes redirect){tasks.postpone(id,days);redirect.addFlashAttribute("successMessage","Task rescheduled. PrepPulse will keep track of the change.");return "redirect:/#tasks";}
}
